userscript.function:

$share.data = {};
doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doDocumentDetail', {
    DOC_NO: docNo,
    MANAGE_NUMBER: manageNo,
    APPLY_TYPE: "NE"
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);
        var manageNumber = soResult.getArrayMap()[0].MANAGE_NUMBER;
        var docNo = soResult.getArrayMap()[0].DOC_NO;

        $share.data.MANAGE_NUMBER = manageNumber;
        $share.data.DOC_NO = docNo;

		var status;
		if (route=='APP') {
			status = 'DETAILAPP';
		} else if (route=='LIST') {
			status = 'DETAIL';
		} else {
        	status = soResult.getArrayMap()[0].STATUS;
        }
        setModeByStatus(status);

        formObj.dataMapper(new SepoaFormater(so.result[0]));
        doLoadImg(manageNo + "_" + docNo);

		formInitSetting();

        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});


$share.data = {};

doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doSealDetail', {
    MANAGE_NUMBER: manageNo,
}, function(so) {
    if (so.status == 1) {
        $share.data.MANAGE_NUMBER = manageNo;

        formObj.dataMapper(new SepoaFormater(so.result[0]));
        doLoadImg(manageNo);
        setModeByStatus('DETAIL')
        formObj.setdisable('SELECT_IMG_BTN', true);
        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});


	$share.data = {};

    doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doSealDetail', {
        MANAGE_NUMBER: manageNo,
    }, function(so) {
        if (so.status == 1) {
            $share.data.MANAGE_NUMBER = manageNo;

            var soResult = new SepoaFormater(so.result[0]);
            formObj.dataMapper(soResult);

            $seal_type = soResult.dataMap.SEAL_TYPE;

            doLoadImg(manageNo);
            setModeByStatus('UPDATE')
            return true;
        } else {
            Alert(Sepoa.cache.text.get('MESSAGE.1002'));
            doBack();
            return false;
        }
    });


if (formObj.getValue('SUBJECT') == "") {
    Alert(Sepoa.cache.text.get('SLM_123.MESSAGE008')); //제목을 입력해주세요.
    return;
}

var files = $sealImgFile;
var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['jpeg', 'jpg', 'png'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                if (callbackObj) {
                    callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
                } else {
                    Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                }
            } else {
                Alert(res.message);
            }
        }
    }
}

var basic_info = getCustomFormData();
basic_info.MANAGE_DOC_NO = $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO;

var serviceData = {
    parameter: {
        basic_info: basic_info
    }
};

var params = {
    module: "seal.management",
    action: "doCreateService",
    CONNECTION: "TRANSACTION",
    CURRENT_PRC: "CREATE",
    MANAGE_DOC_NO: $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO,
    SEAL_DATA: JSON.stringify(serviceData)
}

if (callbackObj || route=='APP') {
    if ($sealImgFile) {
        params.files = $sealImgFile
        sUtils.multipart.upload(config, params);
    } else {
        sUtils.multipart.send(config, params);
    }
} else {
    Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE009'), function(flag) { //저장하시겠습니까?
        if (flag) {
            if ($sealImgFile) {
                params.files = $sealImgFile,
                    sUtils.multipart.upload(config, params);
            } else {
                sUtils.multipart.send(config, params);
            }
        }
    });
}


	if (!formObj.validate()) {
        Alert(Sepoa.cache.text.get("MESSAGE.0002")); //VALIDATION
        return;
    }

    if (!flagValidateCheck()) {
        return;
    }

    if (!formObj.isItemChecked('SEAL_IMG_FLAG')) {
        Alert(Sepoa.cache.text.get('SLM_123.MESSAGE002')); //인감 이미지를 등록해주세요.
        return;
    }

    Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE013'), function(flag) {
        if (flag) {
            var config = {
                multiple: false,
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                ext: ['jpeg', 'jpg', 'png'],
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            Alert(Sepoa.cache.text.get('MESSAGE.0054'));	//성공적으로 저장되었습니다.
                        } else {
                            Alert(res.message);
                        }
                    }
                }
            }

    		var data = getCustomFormData();

            var params = {
                module: "seal.management",
                action: "doSealUpdate",
                CONNECTION: "TRANSACTION",
                MANAGE_NUMBER: $share.data.MANAGE_NUMBER,
                SEAL_DATA: JSON.stringify(data),
            }

    		if ($sealImgFile) {
                params.files = $sealImgFile,
                    sUtils.multipart.upload(config, params);
            } else {
                sUtils.multipart.send(config, params);
            }
        }
    });


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get("MESSAGE.0002")); //VALIDATION
    return;
}

if (!flagValidateCheck()) {
    return;
}

Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE003'), function(flag) { //인감 등록신청을 하시겠습니까?
    if (flag) {
        doSave({
            CALLBACK: doLegalProcess,
            CALLBACK_PARMETER: {
                LEGAL_PRC_TYPE: "LEGAL_REQUEST"
            }
        });
    }
});


if (!formObj.isItemChecked('SEAL_IMG_FLAG')) {
    Alert(Sepoa.cache.text.get('SLM_123.MESSAGE002')); //인감 이미지를 등록해주세요.
    return;
}

Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE001'), function(flag) {
    if (flag) {
        popupReason({
    		title: Sepoa.cache.text.get('SLM_211.CONFIRM_REASON'),
    		callbackFn: doLegalAcceptAfterReason
    	});
    }
});


        	doSave({
        		CALLBACK: doLegalProcess,
        		CALLBACK_PARMETER: {
					LEGAL_PRC_TYPE: "LEGAL_ACCEPT",
					ACCEPT_REASON: obj.APP_COMMENT
				}
		    });

		    return true;


Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE007'), function(flag) {
    if (flag) {
        popupReason({
    		title: Sepoa.cache.text.get('SLM_211.REJECT_REASON'),
    		callbackFn: doLegalRejectAfterReason
    	});
    }
});


        	doSave({
        		CALLBACK: doLegalProcess,
        		CALLBACK_PARMETER: {
					LEGAL_PRC_TYPE: "LEGAL_REJECT",
					ACCEPT_REASON: obj.APP_COMMENT
				}
		    });

		    return true;


        	sUtils.popup.modal({
		        url: '/UxDefault/Common/WindowForm.sux',
		        title: data.title,
		        header: true,
		        params: {
		            mode: 'WRITE',
		            form: 'APP_COMMENT',
		    		callback: data.callbackFn || function() {}
		    	}
		    })


var files = $sealImgFile;
var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['jpeg', 'jpg', 'png'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                if (Sepoa.request.MODE == 'NEW') {
                	linkTo('SLM_180', '/Seal/Manage/SealManageRequestCarousel.sux', 'undefined', Sepoa.cache.text.get('SLM_180.TITLE'));
                    SUX.root.getContentsCell(window).close();
                } else {
                    doBack(callbackParams);
                }
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
            } else {
                Alert(res.message);
            }
        }
    }
}

var basic_info = getCustomFormData();
basic_info.MANAGE_DOC_NO = $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO;
