}


Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE005'), function(flag) { //발송 확인을 하시겠습니까?
    if (flag) {
        var config = {
            multiple: false,
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            ext: ['jpeg', 'jpg', 'png'],
            on: {
                callback: function(res) {
                    if (res.status == "1") {
                        Alert(Sepoa.cache.text.get("MESSAGE.0001"), function() {
                            //등록화면 경우의 수 : 단독으로 들어왔을 때 : 닫아버림  
                            //등록현황에서 들어왔을 때 : doBack 함
                            if (this.request.MODE == "NEW") {
                                SUX.root.getContentsCell(window).close();
                            } else {
                                doBack();
                            }
                        });
                    } else {
                        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0002'));
                        formObj.uncheckItem('SEAL_IMG_FLAG');
                    }
                }
            }
        }

        var data = {
            DOC_NO: $share.data.DOC_NO,
            MANAGE_NUMBER: $share.data.MANAGE_NUMBER,
            SEAL_TYPE: formObj.getValue("SEAL_TYPE")
        }

        var serviceData = {
            parameter: {
                basic_info: data
            }
        };

        var params = {
            module: "seal.management",
            action: "doCreateService",
            CONNECTION: "TRANSACTION",
            CURRENT_PRC: 'SEND',
            SEAL_DATA: JSON.stringify(serviceData)
        }

        sUtils.multipart.send(config, params);
    }
})


Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE006'), function(flag) { //수령하시겠습니까?
    if (flag) {
        var config = {
