	app_type = 'J04';
}

var serviceData = {
    parameter: {
        basic_info: basic_info,
        APP_TYPE: app_type,
		APP_LINE: params.data.approver,
    	APP_INFO: {
        	APP_COMMENT: params.data.comment
    	}
    }
};

var params = {
    module: "seal.management",
