}

sUtils.multipart.send(config, params);


//법무팀 전용 다이렉트 등록용 
if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get("MESSAGE.0002")); //VALIDATION
    return;
}

if (!flagValidateCheck()) {
    return;
}

if (!formObj.isItemChecked('SEAL_IMG_FLAG')) {
    Alert(Sepoa.cache.text.get('SLM_123.MESSAGE002')); //인감 이미지를 등록해주세요.
    return;
}

Confirm(Sepoa.cache.text.get('SLM_123.MESSAGE011'), function(flag) {
    if (flag) {
        doSave({
            CALLBACK: doCompleteProcess,
            CALLBACK_PARMETER: {}
        });
    }
});


var files = $sealImgFile;
var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['jpeg', 'jpg', 'png'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                if (Sepoa.request.MODE == 'NEW') {
                	linkTo('SLM_170', '/Seal/Manage/SealManageRegistCarousel.sux', 'undefined', Sepoa.cache.text.get('SLM_170.TITLE'));
                    SUX.root.getContentsCell(window).close();
                } else {
                    doBack();
                }
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
            } else {
                Alert(res.message);
            }
        }
    }
}

var basic_info = getCustomFormData();
basic_info.MANAGE_DOC_NO = $share.data.MANAGE_NUMBER + '_' + $share.data.DOC_NO;

var serviceData = {
    parameter: {
        basic_info: basic_info
    }
};

var params = {
    module: "seal.management",
    action: "doCreateService",
    CONNECTION: "TRANSACTION",
    CURRENT_PRC: 'COMPLETE',
    SEAL_DATA: JSON.stringify(serviceData)
}

if ($sealImgFile) {
    params.files = $sealImgFile;
    sUtils.multipart.upload(config, params);
} else {
    sUtils.multipart.send(config, params);
}


var container = formObj.getContainer('SEAL_IMG_BOX');
container.innerHTML = '';

var url = window.CONTEXT_NAME + '/SepoaActionController.sux?module=seal.management&action=doImage&MANAGE_DOC_NO=' + docNo;
var sealImg = document.createElement('img');
sealImg.src = url;
sealImg.style.width = '100%';

container.appendChild(sealImg);
setImageCover();
formObj.checkItem('SEAL_IMG_FLAG');

sealImg.onerror = function() {
    sealImgNotFound();
}


$share.data = {};
$share.data.MANAGE_NUMBER = getDocumentNumber("SLM");
$share.data.DOC_NO = getDocumentNumber("SLD");

formObj.setValue('MANAGE_NUMBER', $share.data.MANAGE_NUMBER);
formObj.setValue('DOC_NO', $share.data.DOC_NO);

formInitSetting();


var g = formObj.getFormData();
for (var formName in g) {
    formObj.setReadOnly(formName, true);
}

var formBtnArr = ['SELECT_MANAGER_BTN', 'SELECT_DEPT_BTN', 'SELECT_SEAL_USE_BTN', 'SELECT_IMG_BTN'];
formBtnArr.forEach(function(btn) {
    formObj.setdisable(btn, true);
});


var g = formObj.getFormData();
for (var formName in g) {
    formObj.setReadOnly(formName, false);
}

var defaultReadOnlyItem = ['SEAL_MG_USER_NAME', 'SEAL_MG_DEPT_NAME', 'SEAL_USE_LOC', 'MANAGE_NUMBER'];
defaultReadOnlyItem.forEach(function(item) {
    formObj.setReadOnly(item, true);
})

var formBtnArr = ['SELECT_MANAGER_BTN', 'SELECT_DEPT_BTN', 'SELECT_SEAL_USE_BTN', 'SELECT_IMG_BTN'];
formBtnArr.forEach(function(btn) {
    formObj.setdisable(btn, false);
});

if($seal_type == 'E' || $seal_type == 'C'){
	formObj.setdisable('EXTERNAL_FLAG', true);
}


switch (name) {
    case "SELECT_MANAGER_BTN":
        doOpenManagerPopup();
        break;
    case "SELECT_DEPT_BTN":
        break;
    case "SELECT_SEAL_USE_BTN":
        doOpenSealUsePopup();
        break;
    case "SELECT_IMG_BTN":
        openFileExplorer();
        break;
    case "SAVE":
        doSave();
        break;
    case "UPDATE":
    	doUpdate();
    	break;
    case "LEGAL_REQUEST":
        doLegalRequest();
        break;
    case "BACK":
        doBack();
        break;
    case "LEGAL_ACCEPT":
        doAccept();
        break;
    case "LEGAL_REJECT":
        doReject();
        break;
    case "SEND":
        doSend();
        break;
    case "RECEIVE":
        doReceive();
        break;
    case "APP_REQUEST":
    	doApprovalRequest();
    	break;
    case "REGIST":
        doRegist();
        break;
    default:
        break;
}


//formInitSetting();

switch (status) {
    case "NEW":
        setNewMode();
        vaultInitSetting('upload');
        break;
    case "NEW_RM":
        setEditMode();
        setNewMode();
        vaultInitSetting('upload');
        break;
    case "T":
        setEditMode();
        vaultInitSetting('upload');
        break;
    case "I":
        break;
    case "A":
        break;
    case "R":
        break;
    case "G":
        setReadMode();
        vaultInitSetting('VI');
        break;
    case "O":
        setReadMode();
        vaultInitSetting('VI');
        break;
    case "N":
        setReadMode();
        vaultInitSetting('VI');
        break;
    case "S":
        setReadMode();
        vaultInitSetting('VI');
        break;
    case "V":
        break;
    case "C":
        setReadMode();
        vaultInitSetting('VI');
        break;
    case "DETAIL":
        setReadMode();
        vaultInitSetting('VI');
        break;
    case "DETAILAPP":
    	setReadMode();
    	vaultInitSetting('VI');
    	break;
   	case "UPDATE":
   		setEditMode();
   		vaultInitSetting('upload');
   		break;
    default:
        break;
}
setBtns(status);


hideAllBtn();
$status_val = status; 
switch (status) {
    case "NEW":
        if (this.request.SID) {
            btnObj.btn('BACK').setShow();
        }
        //btnObj.btn('SAVE').setShow();

        if (sUtils.workflow.check('US1635932969714')) { //결재 모듈
            btnObj.btn('APP_REQUEST').setShow();
        }

        if (sUtils.workflow.check('US1635932977187')) { //법무팀 승인 모듈
            btnObj.btn('LEGAL_REQUEST').setShow();
        }

		if (sUtils.workflow.check('US1647931830203') && sUtils.workflow.check('CS1647936818419')
			&& Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1) { //법무팀 등록
            btnObj.btn('REGIST').setShow();
        }

        break;
    case "NEW_RM":
    	btnObj.btn('REGIST').setShow();
        btnObj.btn('BACK').setShow();
        break;
    case "T":
        btnObj.btn('BACK').setShow();
        //btnObj.btn('SAVE').setShow();
        formObj.setdisable('SELECT_IMG_BTN', false);

        if (sUtils.workflow.check('US1635932969714')) { //결재 모듈
            btnObj.btn('APP_REQUEST').setShow();
        }

        if (sUtils.workflow.check('US1635932977187')) { //법무팀 승인 모듈
            btnObj.btn('LEGAL_REQUEST').setShow();
        }

        if (sUtils.workflow.check('US1647931830203') && sUtils.workflow.check('CS1647936818419')
			&& Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1) { //법무팀 등록
            btnObj.btn('REGIST').setShow();
        }

        break;
    case "I":
        break;
    case "A":
        break;
    case "R":
        break;
    case "G":
        if (Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1) {
            btnObj.btn('LEGAL_ACCEPT').setShow();
            btnObj.btn('LEGAL_REJECT').setShow();
            formObj.setdisable('SELECT_IMG_BTN', false);
        }
        btnObj.btn('BACK').setShow();
        break;
    case "O":
        if (Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1) {
            btnObj.btn('SEND').setShow();
        }
        btnObj.btn('BACK').setShow();
        break;
    case "N":
        btnObj.btn('BACK').setShow();
        break;
    case "S":
        btnObj.btn('RECEIVE').setShow();
        btnObj.btn('BACK').setShow();
        break;
    case "V":
        btnObj.btn('BACK').setShow();
        break;
    case "C":
        btnObj.btn('BACK').setShow();
        break;
    case "DETAIL":
        btnObj.btn('BACK').setShow();
        formObj.setdisable('SELECT_IMG_BTN', false);
        break;
    case "DETAILAPP":
    	formObj.setdisable('SELECT_IMG_BTN', false);
